export class Layer {
    constructor(config) {
        if (!config.apiKey) {
            throw new Error('Layer API key is required');
        }
        this.apiKey = config.apiKey;
        this.baseUrl = config.baseUrl || 'https://api.uselayer.ai';
    }
    async request(options) {
        const { method, path, body } = options;
        const url = `${this.baseUrl}${path}`;
        const response = await fetch(url, {
            method,
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${this.apiKey}`,
            },
            body: body ? JSON.stringify(body) : undefined,
        });
        // Handle 204 No Content responses (e.g., DELETE operations)
        if (response.status === 204) {
            return undefined;
        }
        const data = await response.json();
        if (!response.ok) {
            const error = data;
            throw new Error(error.message || error.error);
        }
        return data;
    }
    async complete(request) {
        return this.request({
            method: 'POST',
            path: '/v2/complete',
            body: request,
        });
    }
    /**
     * v3 Chat completion endpoint - Type-safe chat requests
     * @param request - Chat request with gateId and ChatRequest data
     */
    async chat(request) {
        return this.request({
            method: 'POST',
            path: '/v3/chat',
            body: request,
        });
    }
    /**
     * v3 Chat completion endpoint with streaming support - yields chunks as they arrive
     * @param request - Chat request with gateId and ChatRequest data (stream: true is set automatically)
     */
    async *chatStream(request) {
        const url = `${this.baseUrl}/v3/chat`;
        const response = await fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${this.apiKey}`,
            },
            body: JSON.stringify({ ...request, data: { ...request.data, stream: true } }),
        });
        if (!response.ok) {
            const error = await response.json();
            throw new Error(error.message || error.error);
        }
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';
        while (true) {
            const { done, value } = await reader.read();
            if (done)
                break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop() ?? '';
            for (const line of lines) {
                if (!line.startsWith('data: '))
                    continue;
                const payload = line.slice(6).trim();
                if (payload === '[DONE]')
                    return;
                try {
                    yield JSON.parse(payload);
                }
                catch {
                    // skip malformed lines
                }
            }
        }
    }
    /**
     * v3 Image generation endpoint - Type-safe image requests
     * @param request - Image request with gateId and ImageGenerationRequest data
     */
    async image(request) {
        return this.request({
            method: 'POST',
            path: '/v3/image',
            body: request,
        });
    }
    /**
     * v3 Video generation endpoint - Type-safe video requests
     * @param request - Video request with gateId and VideoGenerationRequest data
     */
    async video(request) {
        return this.request({
            method: 'POST',
            path: '/v3/video',
            body: request,
        });
    }
    /**
     * v3 Embeddings endpoint - Type-safe embeddings requests
     * @param request - Embeddings request with gateId and EmbeddingsRequest data
     */
    async embeddings(request) {
        return this.request({
            method: 'POST',
            path: '/v3/embeddings',
            body: request,
        });
    }
    /**
     * v3 Text-to-Speech endpoint - Type-safe TTS requests
     * @param request - TTS request with gateId and TextToSpeechRequest data
     */
    async tts(request) {
        return this.request({
            method: 'POST',
            path: '/v3/tts',
            body: request,
        });
    }
    /**
     * v3 OCR endpoint - Type-safe OCR requests
     * @param request - OCR request with gateId and OCRRequest data
     */
    async ocr(request) {
        return this.request({
            method: 'POST',
            path: '/v3/ocr',
            body: request,
        });
    }
}
